// Generated by Codex and not thoroughly checked for correctness.
func TestUsageLimitsIntegration(t *testing.T) {
	database := testutil.OpenTestDB(t)
	database.SetMaxOpenConns(10)
	listRepository := lists.NewRepository(database, configs.DefaultDatabaseTimeout)
	itemRepository := items.NewRepository(database, configs.DefaultDatabaseTimeout)

	t.Run("concurrent list inserts cannot exceed 20 and deletion restores capacity", func(t *testing.T) {
		ownerID, otherID := resetListIntegrationState(t, database)
		seedQuotaLists(t, database, ownerID, limits.ListsPerUser-1)
		assertConcurrentQuota(t, limits.ErrListQuota, func(index int) error {
			return listRepository.Create(t.Context(), ownerID, &lists.List{Name: fmt.Sprintf("candidate-%d", index)})
		})
		stored, err := listRepository.GetAllListByUserId(t.Context(), ownerID)
		if err != nil || len(stored) != limits.ListsPerUser {
			t.Fatalf("stored lists=%d error=%v", len(stored), err)
		}
		createIntegrationList(t, listRepository, otherID, "independent capacity")
		if err := listRepository.Delete(t.Context(), ownerID, stored[0].Id); err != nil {
			t.Fatal(err)
		}
		createIntegrationList(t, listRepository, ownerID, "after deletion")
	})

	t.Run("concurrent item inserts cannot exceed 1000 and preserve ownership", func(t *testing.T) {
		ownerID, otherID := resetListIntegrationState(t, database)
		list := createIntegrationList(t, listRepository, ownerID, "owned")
		seedQuotaItems(t, database, list.Id, limits.ItemsPerList-1)
		assertConcurrentQuota(t, limits.ErrItemQuota, func(index int) error {
			return itemRepository.Create(t.Context(), ownerID, &items.ListItem{ListId: list.Id, ProblemId: fmt.Sprintf("candidate-%d", index), Position: index})
		})
		stored, err := itemRepository.GetItems(t.Context(), ownerID, list.Id)
		if err != nil || len(stored) != limits.ItemsPerList {
			t.Fatalf("stored items=%d error=%v", len(stored), err)
		}
		foreign := items.ListItem{ListId: list.Id, ProblemId: "foreign"}
		if err := itemRepository.Create(t.Context(), otherID, &foreign); !errors.Is(err, items.ErrListNotFound) {
			t.Fatalf("foreign insert error=%v", err)
		}
		otherList := createIntegrationList(t, listRepository, ownerID, "independent list")
		if err := itemRepository.Create(t.Context(), ownerID, &items.ListItem{ListId: otherList.Id, ProblemId: "independent"}); err != nil {
			t.Fatal(err)
		}
		if err := itemRepository.Delete(t.Context(), ownerID, &stored[0]); err != nil {
			t.Fatal(err)
		}
		if err := itemRepository.Create(t.Context(), ownerID, &items.ListItem{ListId: list.Id, ProblemId: "after-deletion"}); err != nil {
			t.Fatal(err)
		}
	})

	t.Run("reads return complete existing list collections without a read-time cap", func(t *testing.T) {
		ownerID, _ := resetListIntegrationState(t, database)
		seedQuotaLists(t, database, ownerID, limits.ListsPerUser+1)
		if stored, err := listRepository.GetAllListByUserId(t.Context(), ownerID); err != nil || len(stored) != limits.ListsPerUser+1 {
			t.Fatalf("lists=%d error=%v", len(stored), err)
		}
		var firstID int64
		if err := database.QueryRowContext(t.Context(), `SELECT MIN(id) FROM lists WHERE user_id=$1`, ownerID).Scan(&firstID); err != nil {
			t.Fatal(err)
		}
		if err := listRepository.Delete(t.Context(), ownerID, firstID); err != nil {
			t.Fatal(err)
		}
		if stored, err := listRepository.GetAllListByUserId(t.Context(), ownerID); err != nil || len(stored) != limits.ListsPerUser {
			t.Fatalf("lists=%d error=%v", len(stored), err)
		}
	})

	t.Run("reads return complete existing item collections without a read-time cap", func(t *testing.T) {
		ownerID, _ := resetListIntegrationState(t, database)
		list := createIntegrationList(t, listRepository, ownerID, "owned")
		seedQuotaItems(t, database, list.Id, limits.ItemsPerList+1)
		if stored, err := itemRepository.GetItems(t.Context(), ownerID, list.Id); err != nil || len(stored) != limits.ItemsPerList+1 {
			t.Fatalf("items=%d error=%v", len(stored), err)
		}
		if err := itemRepository.Delete(t.Context(), ownerID, &items.ListItem{ListId: list.Id, ProblemId: "seed-1"}); err != nil {
			t.Fatal(err)
		}
		if stored, err := itemRepository.GetItems(t.Context(), ownerID, list.Id); err != nil || len(stored) != limits.ItemsPerList {
			t.Fatalf("items=%d error=%v", len(stored), err)
		}
	})

	t.Run("repository validates names on writes and returns complete names on reads", func(t *testing.T) {
		ownerID, _ := resetListIntegrationState(t, database)
		list := createIntegrationList(t, listRepository, ownerID, " "+strings.Repeat("界", limits.ListNameCharacters)+" ")
		if list.Name != strings.Repeat("界", limits.ListNameCharacters) {
			t.Fatal("repository did not trim name")
		}
		invalid := lists.List{Id: list.Id, Name: strings.Repeat("界", limits.ListNameCharacters+1)}
		if err := listRepository.Create(t.Context(), ownerID, &invalid); !errors.Is(err, limits.ErrInvalidListName) {
			t.Fatalf("create invalid error=%v", err)
		}
		if err := listRepository.UpdateName(t.Context(), ownerID, &invalid); !errors.Is(err, limits.ErrInvalidListName) {
			t.Fatalf("rename invalid error=%v", err)
		}
		storedName := strings.Repeat("界", 20000)
		if _, err := database.ExecContext(t.Context(), `UPDATE lists SET name=$1 WHERE id=$2`, storedName, list.Id); err != nil {
			t.Fatal(err)
		}
		if stored, err := listRepository.GetById(t.Context(), ownerID, list.Id); err != nil || stored.Name != storedName {
			t.Fatalf("legacy list=%v error=%v", stored, err)
		}
		if stored, err := listRepository.GetAllListByUserId(t.Context(), ownerID); err != nil || len(stored) != 1 || stored[0].Name != storedName {
			t.Fatalf("legacy lists=%v error=%v", stored, err)
		}
		list.Name = "valid again"
		if err := listRepository.UpdateName(t.Context(), ownerID, &list); err != nil {
			t.Fatal(err)
		}
		if _, err := listRepository.GetById(t.Context(), ownerID, list.Id); err != nil {
			t.Fatal(err)
		}
	})
}

func seedQuotaLists(t *testing.T, database *sql.DB, ownerID int64, count int) {
	t.Helper()
	if _, err := database.ExecContext(t.Context(), `INSERT INTO lists(user_id, name)
		SELECT $1, 'seed-' || n FROM generate_series(1, $2::int) AS n`, ownerID, count); err != nil {
		t.Fatal(err)
	}
}

func seedQuotaItems(t *testing.T, database *sql.DB, listID int64, count int) {
	t.Helper()
	if _, err := database.ExecContext(t.Context(), `INSERT INTO list_items(list_id, problem_id, position)
		SELECT $1, 'seed-' || n, n FROM generate_series(1, $2::int) AS n`, listID, count); err != nil {
		t.Fatal(err)
	}
}

func assertConcurrentQuota(t *testing.T, quota error, operation func(int) error) {
	t.Helper()
	const attempts = 8
	results := make(chan error, attempts)
	start := make(chan struct{})
	var workers sync.WaitGroup
	for index := range attempts {
		workers.Go(func() { <-start; results <- operation(index) })
	}
	close(start)
	workers.Wait()
	close(results)
	accepted := 0
	for err := range results {
		if err == nil {
			accepted++
		} else if !errors.Is(err, quota) {
			t.Fatalf("concurrent insert error=%v", err)
		}
	}
	if accepted != 1 {
		t.Fatalf("accepted inserts=%d, want exactly 1 remaining slot", accepted)
	}
}
